import Foundation

struct HomeMealAction: Codable {
    let kind: String
    let title: String
    let text: String
    let seconds: Int
    let ingredients: [String]
    let heat: HeatLevel?
    let destination: String
}
struct HomeMealTemplate: Codable {
    let title: String
    let category: String
    let detail: String
    let amounts: [String: Double]
    let essential: [String]
    let waterML: Int
    let flow: [HomeMealAction]
    let cuts: [String: String]
    let sourceStatus: String?
    let sourceNotes: String?
    let oneServingAmounts: [String: Double]?
    let oneServingWaterML: Int?
    let fixedBatch: Bool?
}
enum HomeMealCatalog {
    static let addedIngredientIDs: Set<String> = ["egg", "chicken", "squid", "carrot", "beanSprout", "spinach", "cucumber", "seaweed", "driedAnchovy", "riceCooked", "tunaCan", "sesameOil", "sesame", "vinegar", "mayonnaise"]
    static let templates: [String: HomeMealTemplate] = {
        guard let data = source.data(using: .utf8), let result = try? JSONDecoder().decode([String: HomeMealTemplate].self, from: data) else { preconditionFailure("집밥 레시피 데이터 형식 오류") }
        guard let personal = personalSource.data(using: .utf8), let overrides = try? JSONDecoder().decode([String: HomeMealTemplate].self, from: personal) else { preconditionFailure("개인 레시피북 데이터 오류") }
        return result.merging(overrides) { _, personal in personal }
    }()
    static func generate(menu: RecipeMenu, kitchen: KitchenProfile?, selected: Set<String>, quantities: [String: Double], preferences: Preferences) throws -> Recipe {
        guard let template = templates[menu.rawValue] else { throw RecipeError.invalid("메뉴를 찾을 수 없습니다.") }
        let profile = kitchen ?? .generalGuidance()
        guard profile.validationErrors().isEmpty, (1...4).contains(preferences.servings) else { throw RecipeError.invalid("주방 설정과 인분을 확인해주세요.") }
        let essentials = Set(template.amounts.keys)
        guard essentials.isSubset(of: selected) else { throw RecipeError.invalid("\(menu.title)의 필수 재료를 선택해주세요: \(essentials.sorted().compactMap { Catalog.item($0)?.name }.joined(separator: ", "))") }
        guard selected.isSubset(of: Set(template.amounts.keys)) else { throw RecipeError.invalid("이 메뉴에 맞는 재료를 선택해주세요.") }
        let scale = Double(preferences.servings) / 2
        var items: [RecipeItem] = []
        var warnings = ["집밥 메뉴 구성을 참고해 앱용으로 작성한 기본 레시피입니다. 화력과 시간은 실제 익힘 상태를 확인하며 조절해주세요.", HouseholdMeasure.guide]
        if template.sourceStatus != nil {
            warnings[0] = "기본 레시피입니다. 타이머는 참고값이며 실제 익힘 상태에 맞춰 조절해주세요."
            if let notes = template.sourceNotes, !notes.isEmpty { warnings.append(notes) }
        }
        for id in template.amounts.keys.sorted() where selected.contains(id) {
            guard let original = Catalog.item(id) else { throw RecipeError.invalid("지원하지 않는 재료입니다.") }
            guard !(preferences.excludeMeat && original.group == "meat") else { throw RecipeError.invalid("육류 제외와 \(original.name) 선택이 충돌합니다.") }
            guard !(preferences.excludeSeafood && original.group == "seafood") else { throw RecipeError.invalid("해산물 제외와 \(original.name) 선택이 충돌합니다.") }
            var amount = preferences.servings == 1 ? (template.oneServingAmounts?[id] ?? template.amounts[id]! / 2) : template.amounts[id]! * scale
            if template.sourceStatus == nil && ["gochujang", "chiliPowder", "chili"].contains(id) { amount *= [0.25, 1, 1.3, 1.6][max(0, min(3, preferences.spice))] }
            if template.sourceStatus == nil && ["salt", "soySauce", "soupSoy", "doenjang"].contains(id) { amount *= [0.8, 1, 1.1, 1.2][max(0, min(3, preferences.salt))] }
            if let available = quantities[id] {
                guard available.isFinite, available > 0 else { throw RecipeError.invalid("\(original.name) 보유량은 0보다 커야 합니다.") }
                if available < amount { amount = available; warnings.append("\(original.name)은 보유량에 맞춰 줄였습니다. 남은 조리 시간은 직접 익힘을 확인해주세요.") }
            }
            // Fractional eggs are measured after beating; whole-count guidance must not round up pantry quantities.
            let ingredient = Ingredient(id, original.name, original.category, original.unit, original.baseAmount, template.cuts[id] ?? original.cut, original.group)
            items.append(.init(ingredient: ingredient, amount: amount))
        }
        var steps: [CookingStep] = []
        var currentHeat: HeatLevel = .off
        func append(_ action: ActionType, _ title: String, _ text: String, duration: Int = 0, required: [RecipeItem] = []) {
            steps.append(.init(actionType: action, title: title, instruction: text, heatFrom: currentHeat, heatTo: currentHeat, deviceSetting: profile.setting(currentHeat), heatGoal: currentHeat.label, durationSeconds: duration, requiredItems: required, completionCondition: "시간과 실제 상태를 확인하고 완료해주세요.", safetyNotice: "뜨거운 용기·기름·증기에 주의하고 넘치거나 연기가 나면 즉시 전원을 끄세요."))
        }
        func change(_ target: HeatLevel) {
            guard target != currentHeat else { return }
            let before = currentHeat; currentHeat = target
            steps.append(.init(actionType: .heat, title: target == .off ? "가열 종료" : "\(target.label)로 설정", instruction: "\(profile.heatingName)의 \(profile.burner)를 \(profile.setting(target))로 조절한 뒤 실제 설정을 확인해주세요.", heatFrom: before, heatTo: target, deviceSetting: profile.setting(target), heatGoal: target.label, durationSeconds: 0, requiredItems: [], completionCondition: "가열기 설정 직접 확인", safetyNotice: "앱이 가열기를 제어하지 않습니다."))
        }
        append(.check, "조리 준비 확인", "계량한 재료와 조리 도구를 준비하고 가열기 OFF를 확인해주세요.")
        if template.flow.contains(where: { $0.kind == "heat" && $0.heat != .off }) {
            append(.placement, "조리 용기 배치", "레시피에 맞는 팬 또는 냄비를 \(profile.burner)에 안정적으로 놓아주세요. 재료와 국물을 담을 여유를 확인하세요.")
        } else { append(.placement, "무침 그릇 준비", "재료를 버무릴 깨끗한 그릇을 준비해주세요. 가열기는 사용하지 않습니다.") }
        let water = preferences.servings == 1 ? (template.oneServingWaterML ?? Int((Double(template.waterML) / 2).rounded())) : Int((Double(template.waterML) * scale).rounded())
        for action in template.flow {
            switch action.kind {
            case "heat": if let target = action.heat { change(target) }
            case "water": if water > 0 { append(.add, "물 계량해 붓기", "물 \(HouseholdMeasure.water(water))를 \(action.destination)에 천천히 부어주세요.") }
            case "add":
                for id in action.ingredients { if let item = items.first(where: { $0.id == id }) {
                    let preparation = item.ingredient.cut.isEmpty ? "계량한" : "\(item.ingredient.cut)으로 준비한"
                    append(.add, "\(item.ingredient.name) 넣기", "\(preparation) \(item.ingredient.name) \(HouseholdMeasure.object(item)) \(action.destination)에 넣어주세요.", required: [item])
                } }
            default:
                let type = ActionType(rawValue: action.kind) ?? .check
                let directions = action.text.replacingOccurrences(of: "{starchAmount}", with: KitchenProfile.number(5 * scale)).replacingOccurrences(of: "{starchWater}", with: KitchenProfile.number(10 * scale)).replacingOccurrences(of: "{pastaWater}", with: preferences.servings == 1 ? "80~120" : "\(75 * preferences.servings)~\(110 * preferences.servings)").replacingOccurrences(of: "{vongoleWater}", with: KitchenProfile.number(75 * Double(preferences.servings)))
                append(type, action.title, directions + (action.seconds > 0 ? "\n시작을 눌러 \(RecipeEngine.time(action.seconds)) 타이머를 실행하고, 실제 상태가 부족하면 연장해주세요." : ""), duration: action.seconds)
            }
        }
        change(.off)
        append(.finish, "완성 확인", "가열기 OFF를 확인하고 음식의 익힘을 직접 확인해주세요. 뜨거운 용기는 맨손으로 잡지 마세요.")
        if profile.usesGeneralGuidance == true { warnings.append("주방 등록 없이 일반 화력으로 안내합니다. 실제 가열 상태를 보며 조절해주세요.") }
        if items.contains(where: { $0.ingredient.group == "meat" }) { warnings.append("육류는 가장 두꺼운 부분의 중심온도 75°C에서 1분 이상을 확인하세요. 시간만으로 익힘을 보증하지 않습니다.") }
        if items.contains(where: { $0.ingredient.group == "seafood" && $0.id != "tunaCan" && $0.id != "driedAnchovy" }) { warnings.append("해산물은 중심온도 85°C에서 1분 이상을 확인하세요. 실제 익힘이 부족하면 추가 가열하세요.") }
        if items.contains(where: { $0.id == "riceCooked" }) { warnings.append("갓 지었거나 냉장 보관한 밥을 사용하세요. 볶음밥은 전체가 충분히 뜨겁게 가열됐는지 확인해주세요.") }
        if let egg = items.first(where: { $0.id == "egg" }), egg.amount.rounded() != egg.amount { warnings.append("달걀 반 개는 달걀물을 고르게 풀어 나누어 계량해주세요.") }
        var prefs = preferences; prefs.saute = false
        var result = Recipe(kitchen: profile, preferences: prefs, items: items, waterML: water, steps: steps, warnings: warnings)
        result.menu = menu; result.templateVersion = template.sourceStatus == nil ? "2.0-home-meals" : "3.0-personal-recipe-book"
        try RecipeEngine.validate(result, selected: selected)
        return result
    }
